import{_ as e,o as a,c as i,aj as n}from"./framework.js";const p=JSON.parse('{"title":"Create Your First Site | Documentation","description":"After signing in, you enter the site list. This is an account-level page and does not contain a SiteId. If you already have a site, select Manage on its card to enter site Admin.","frontmatter":{"title":"Create Your First Site | Documentation","description":"After signing in, you enter the site list. This is an account-level page and does not contain a SiteId. If you already have a site, select Manage on its card to enter site Admin.","head":[["link",{"rel":"canonical","href":"https://docs.kooboo.com/quick-start/create-first-site.html"}]]},"headers":[],"relativePath":"quick-start/create-first-site.md","filePath":"en/quick-start/create-first-site.md","lastUpdated":1787045655000}'),r={name:"quick-start/create-first-site.md"};function s(d,t,o,c,l,h){return a(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="create-your-first-site" tabindex="-1">Create Your First Site <a class="header-anchor" href="#create-your-first-site" aria-label="Permalink to &quot;Create Your First Site&quot;">​</a></h1><blockquote><p>Go from signing in to opening the site administration page.</p></blockquote><h2 id="sign-in-and-confirm-the-entry-point" tabindex="-1">Sign In and Confirm the Entry Point <a class="header-anchor" href="#sign-in-and-confirm-the-entry-point" aria-label="Permalink to &quot;Sign In and Confirm the Entry Point&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Details</th></tr></thead><tbody><tr><td>Admin entry</td><td><code>/_Admin/</code></td></tr><tr><td>Legacy path compatibility</td><td><code>/_Admin/Sites</code> returns to the site list</td></tr><tr><td>Main pages</td><td>Site list, folders, and site creation</td></tr></tbody></table><p>After signing in, you enter the site list. This is an account-level page and does not contain a <code>SiteId</code>. If you already have a site, select <strong>Manage</strong> on its card to enter site Admin.</p><h2 id="create-a-site" tabindex="-1">Create a Site <a class="header-anchor" href="#create-a-site" aria-label="Permalink to &quot;Create a Site&quot;">​</a></h2><p>Admin provides three common methods:</p><table tabindex="0"><thead><tr><th>Method</th><th>Deep link</th><th>Recommended use</th></tr></thead><tbody><tr><td>Blank site</td><td><code>/_Admin/create</code></td><td>Start with the smallest site structure</td></tr><tr><td>Import site</td><td><code>/_Admin/create/import</code></td><td>Import an existing site package, ZIP file, or migration source</td></tr><tr><td>Clone site</td><td><code>/_Admin/create/clone</code></td><td>Copy an existing site as the starting point for a new project</td></tr></tbody></table><p>If template-based site creation is available in your environment, select a template from the site creation flow and review its name, domain, and source before creating the site.</p><h2 id="enter-site-admin-for-the-first-time" tabindex="-1">Enter Site Admin for the First Time <a class="header-anchor" href="#enter-site-admin-for-the-first-time" aria-label="Permalink to &quot;Enter Site Admin for the First Time&quot;">​</a></h2><p>After entering site Admin, the URL normally contains the site ID:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/_Admin/site/dashboard?SiteId={site-guid}</span></span></code></pre></div><p>Site-level deep links in the CMS documentation use the same format. Replace <code>{site-guid}</code> with the <code>SiteId</code> from the address bar of your current site.</p><h2 id="recommended-initial-checks" tabindex="-1">Recommended Initial Checks <a class="header-anchor" href="#recommended-initial-checks" aria-label="Permalink to &quot;Recommended Initial Checks&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Check</th><th>Location</th></tr></thead><tbody><tr><td>Site name, default language, and Base URL</td><td><a href="/kb-docs/cms/settings/basic/general.html">Basic Settings: General</a></td></tr><tr><td>Whether the site needs multiple languages</td><td><a href="/kb-docs/cms/settings/basic/general.html">Basic Settings: General</a> and <a href="/kb-docs/cms/development/spa-multilingual.html">SPA Multilingual</a></td></tr><tr><td>Whether the site needs team collaboration</td><td><a href="/kb-docs/cms/settings/site-users.html">Site Users</a> and <a href="/kb-docs/cms/settings/roles.html">Roles</a></td></tr><tr><td>Whether the site needs AI capabilities</td><td><a href="/kb-docs/cms/settings/ai-service.html">AI Service</a></td></tr></tbody></table><h2 id="next-step" tabindex="-1">Next Step <a class="header-anchor" href="#next-step" aria-label="Permalink to &quot;Next Step&quot;">​</a></h2><p>Continue to <a href="./build-first-page.html">Build Your First Page</a>.</p>',17)])])}const u=e(r,[["render",s]]);export{p as __pageData,u as default};
